-- まさ 2026-10-06: 指定資料v0.9の15か月現金予算を共通試算表に採用。
BEGIN;
DO $$ BEGIN IF (SELECT count(*) FROM project_monthly_cashflow WHERE project_id='p21' AND ym BETWEEN '2027-04' AND '2028-06' AND planning_details_json->>'version'='sol-finance-2026-09-30') <> 15 THEN RAISE EXCEPTION 'Source plan changed; readback required'; END IF; END $$;
DO $$ BEGIN IF (SELECT planning_details_json FROM project_monthly_cashflow WHERE project_id='p21' AND ym='2027-04') IS DISTINCT FROM $before${"summary": {"asOf": "2026-09-30", "cases": [{"key": "adopted", "description": "2027年10月交付決定、支払完了から3か月後のNEDO入金。追加出資なし。"}, {"key": "receipt_delay", "description": "交付決定は2027年10月、NEDO入金が支払完了から6か月後へ遅延。追加出資なし。"}, {"key": "approval_delay", "description": "交付決定が2028年4月へ遅延し、決定前の支出は補助対象外。2028年1月にブリッジ3,500万円を仮置き。"}, {"key": "rejected", "description": "STS不採択。補助金・つなぎ融資とも利用せず、2028年1月にブリッジ4,000万円を仮置き。"}], "endYm": "2028-06", "source": {"cutoff": "2028年6月までを今回改定。シリーズA以降の事業・損益・大型投資計画は再精査する。", "workbookSha256": "74dabd0ee8018aa2bbc976b5725c8c3a1b6c1bc41ec6b424b5c394634acd5532", "adoptedMaterial": "いよぎん様へのお願い v3.3（2026-09-30）"}, "startYm": "2027-04", "version": "sol-finance-2026-09-30", "discount": 0.2, "equipment": [{"note": "装置販売／提供を想定。基本は対象外。研究用保有・貸与等の整理後に変更。", "label": "有償PoC装置 1号機", "orderYm": "2027-10", "amountYen": 6600000, "deliveryYm": "2027-12"}, {"note": "同上。金額・仕様・見積は未確定。", "label": "有償PoC装置 2号機", "orderYm": "2027-12", "amountYen": 6600000, "deliveryYm": "2028-02"}, {"note": "同上。有償PoCは3件。", "label": "有償PoC装置 3号機", "orderYm": "2028-02", "amountYen": 6600000, "deliveryYm": "2028-04"}, {"note": "研究開発に専用、自社保有。交付後発注を仮定。装置仕様・見積未確定。", "label": "培養スケールアップ設備", "orderYm": "2027-10", "amountYen": 16500000, "deliveryYm": "2027-11"}, {"note": "前期試作。基本ケースでは交付前のため補助対象から除外。", "label": "カートリッジ・充填試作 前期", "orderYm": "2027-07", "amountYen": 2200000, "deliveryYm": "2027-08"}, {"note": "研究用の試作・充填・再試験。初期充填費を含み、月次消耗品と重複させない。", "label": "カートリッジ・充填試作 後期", "orderYm": "2027-11", "amountYen": 4400000, "deliveryYm": "2028-01"}, {"note": "研究用専用機器。汎用機器・他事業共用を含めない前提。", "label": "測定・品質評価機器", "orderYm": "2027-10", "amountYen": 4400000, "deliveryYm": "2027-10"}, {"note": "納品装置側の費用。研究開発費の認定前は補助対象0%。", "label": "PoC現地輸送・据付 1", "orderYm": "2027-11", "amountYen": 1100000, "deliveryYm": "2027-12"}, {"note": "同上。", "label": "PoC現地輸送・据付 2", "orderYm": "2028-01", "amountYen": 1100000, "deliveryYm": "2028-02"}, {"note": "同上。", "label": "PoC現地輸送・据付 3", "orderYm": "2028-03", "amountYen": 1100000, "deliveryYm": "2028-04"}, {"note": "研究設備の変更・交換部品。量産のみの改修は含めない。", "label": "研究設備の予備部品・改修", "orderYm": "2028-01", "amountYen": 2200000, "deliveryYm": "2028-03"}, {"note": "支出を予算に含めるが、使途未定なのでSTS対象には計上しない。", "label": "設備費の未配賦予備費", "orderYm": "2028-06", "amountYen": 2200000, "deliveryYm": "2028-06"}, {"note": "設立後にNewCoが負担する分の仮置き。設立前の負担は別管理。税区分要精査。", "label": "設立・契約・初期法務", "orderYm": "2027-04", "amountYen": 1650000, "deliveryYm": "2027-04"}, {"note": "必要有無・金額とも仮定。返還入金はシードまで見込まない。", "label": "ラボ保証金等", "orderYm": "2027-04", "amountYen": 360000, "deliveryYm": "2027-04"}, {"note": "入居工事・備品の仮置き。交付前の支出。", "label": "ラボ整備・初期備品", "orderYm": "2027-04", "amountYen": 1254000, "deliveryYm": "2027-05"}, {"note": "SOL帰属の研究成果・期間内出願を仮定。共同出願持分により要調整。", "label": "研究成果の特許出願等", "orderYm": "2027-11", "amountYen": 1650000, "deliveryYm": "2028-01"}, {"note": "初期契約費等の仮置き。条件未合意。新たな研究成果の特許出願費とは分離。", "label": "大学の既存知財利用関連", "orderYm": "2027-04", "amountYen": 550000, "deliveryYm": "2027-04"}], "reserveYen": 13076347, "assumptions": ["2027年4月1日設立・シード1億円入金、2028年7月シリーズA入金を目標とする。いずれも契約・入金実績ではない。", "シードはJ-KISS 2.0、ポストマネー・キャップ5億円、ディスカウント20％の協議案。シリーズAの新規株式調達1億円以上を転換条件とする案。シリーズAの調達額・評価額は再精査する。", "基本ケースは2027年10月交付決定、補助率2/3、対象支出の支払完了から3か月後にNEDO入金。交付決定前の発注・契約は対象外として試算。採択・対象経費・入金日は未確定。", "対象支出の補助見込分を原則支払前月に借入。交付決定月は決定後・支払前に借入。NEDO入金と同月に元本を返済。融資は年利2％・手数料0円の仮定で、約3,000万円の枠を協議する。", "大学共同研究費は間接経費込み年1,000万円。半年ごとの契約・四半期末支払を仮定。大学の間接経費率30％は内訳表示用の仮定で、総額に追加しない。", "有償PoCは3件を計画。販売価格・前受金条件が未定のため、売上・入金は0円で試算。顧客へ納品する装置・据付費はSTS対象に含めない。", "AMD委託料とCEO報酬はSTS対象0円。開発担当は仮の時間単価4,000円×月128時間で積算。ラボ賃料は研究専用100％、旅費50％、消耗品・光熱費80％の仮按分。対象認定は公募・交付条件に従って確認する。", "費用・PoC入金条件による手元資金1,000万円の改善は未達の管理目標。補助金減少・税負担を控除した純改善額を指し、月次入金や費用削減として計上しない。", "6月末の借入残高447万円には7月支払に備えた借入約70万円を含む。シリーズAの入金後も、対応するNEDO入金で返済する。", "金額は管理用の支払予算。設備・初期費用には装置・試作・法務・保証金等を含む。資産・在庫・費用の会計区分、減価償却、税額・還付は別途精査する。"], "nextRoundYm": "2028-07", "bridgePolicy": ["不採択時は補助金・NEDOを返済原資とするつなぎ融資とも0円。採否判明時に調達と支出を再計画し、2028年1月までのブリッジ払込を目標とする。", "現行費用で3か月分の手元資金を残す必要額は約3,894万円、比較用の調達額は4,000万円。純改善1,000万円を達成できれば必要額約2,894万円、比較用調達額3,000万円。約5,000万円は検討枠であり、全額の調達を確定していない。", "キャップ適用時のシード持分目安は1億円÷5億円＝20％（シリーズAの新規出資による希薄化前）。20％未満という当初希望とは一致しない。同じキャップでブリッジ3,000万円・4,000万円・5,000万円を重ねると単純計算で26％・28％・30％。累計25％以内を目指すには金額またはブリッジ条件の再設計が必要。"], "monthlyCosts": [{"label": "大学共同研究費・間接費込み", "status": "今回指定", "amountYen": 833333}, {"label": "チームアルマダ委託料", "status": "今回指定", "amountYen": 600000}, {"label": "CEO役員報酬・額面", "status": "今回指定", "amountYen": 900000}, {"label": "CEOの会社負担社保等", "status": "仮定", "amountYen": 120000}, {"label": "開発担当者・会社負担込み", "status": "仮定", "amountYen": 800000}, {"label": "ラボ賃料・52㎡一般利用", "status": "仮定", "amountYen": 119600}, {"label": "旅費", "status": "今回指定", "amountYen": 200000}, {"label": "消耗品・外部分析", "status": "仮定", "amountYen": 250000}, {"label": "光熱・共用設備・廃棄物", "status": "仮定", "amountYen": 150000}, {"label": "会計・法務・保険・通信", "status": "仮定", "amountYen": 150000}], "seedAmountYen": 100000000, "postMoneyCapYen": 500000000, "bridgeEnvelopeYen": 50000000, "nextRoundAmountYen": null, "conversionTriggerYen": 100000000, "improvementTargetYen": 10000000, "loanFacilityTargetYen": 30000000}, "version": "sol-finance-2026-09-30", "scenarios": [{"key": "adopted", "label": "STS採択", "closingYen": 93627240, "openingYen": 0, "interestYen": 0, "peakLoanYen": 0, "roundingYen": 0, "seedInflowYen": 100000000, "loanBalanceYen": 0, "netCashFlowYen": 93627240, "bridgeInflowYen": 0, "grantReceiptYen": 0, "loanDrawdownYen": 0, "loanRepaymentYen": 0, "ordinarySpendYen": 3436560, "equipmentSpendYen": 2936200}, {"key": "receipt_delay", "label": "入金遅延", "closingYen": 93627240, "openingYen": 0, "interestYen": 0, "peakLoanYen": 0, "roundingYen": 0, "seedInflowYen": 100000000, "loanBalanceYen": 0, "netCashFlowYen": 93627240, "bridgeInflowYen": 0, "grantReceiptYen": 0, "loanDrawdownYen": 0, "loanRepaymentYen": 0, "ordinarySpendYen": 3436560, "equipmentSpendYen": 2936200}, {"key": "approval_delay", "label": "交付遅延", "closingYen": 93627240, "openingYen": 0, "interestYen": 0, "peakLoanYen": 0, "roundingYen": 0, "seedInflowYen": 100000000, "loanBalanceYen": 0, "netCashFlowYen": 93627240, "bridgeInflowYen": 0, "grantReceiptYen": 0, "loanDrawdownYen": 0, "loanRepaymentYen": 0, "ordinarySpendYen": 3436560, "equipmentSpendYen": 2936200}, {"key": "rejected", "label": "STS不採択", "closingYen": 93627240, "openingYen": 0, "interestYen": 0, "peakLoanYen": 0, "roundingYen": 0, "seedInflowYen": 100000000, "loanBalanceYen": 0, "netCashFlowYen": 93627240, "bridgeInflowYen": 0, "grantReceiptYen": 0, "loanDrawdownYen": 0, "loanRepaymentYen": 0, "ordinarySpendYen": 3436560, "equipmentSpendYen": 2936200}]}$before$::jsonb THEN RAISE EXCEPTION 'Source month changed; readback required'; END IF; END $$;
UPDATE project_monthly_cashflow SET planning_details_json=$plan${"version": "sol-finance-2026-10-06-v0.9", "scenarios": [{"key": "adopted", "label": "資料v0.9・主ケース", "openingYen": 0, "ordinarySpendYen": 3633560, "equipmentSpendYen": 2936200, "interestYen": 0, "seedInflowYen": 100000000, "bridgeInflowYen": 0, "loanDrawdownYen": 0, "grantReceiptYen": 0, "loanRepaymentYen": 0, "loanBalanceYen": 0, "peakLoanYen": 0, "salesReceiptYen": 0, "netCashFlowYen": 93430240, "closingYen": 93430240, "roundingYen": 0}], "summary": {"asOf": "2026-10-06", "cases": [{"key": "adopted", "description": "指定資料v0.9の主ケース：シード1億円、STS・つなぎ融資、リアクター3台、共同開発3件。受注・採択・融資は計画条件。"}], "endYm": "2028-06", "source": {"workbookSha256": "5ab642d4a03e51eb2dd1dffa5dc2c22a3b6244c075220a9869f51296835bfad6", "adoptedMaterial": "シリーズAまでの事業計画・予算案 v0.9（2026-10-06）", "cutoff": "設立後15か月（2027年4月〜2028年6月）の主ケース。2028年7月以降の登録値は今回の対象外。"}, "startYm": "2027-04", "version": "sol-finance-2026-10-06-v0.9", "discount": 0.2, "equipment": [], "reserveYen": 13780680, "assumptions": ["2027年4月にシード出資1億円を受領する計算。正式契約・実入金は別。資本政策表の調達条件は変更しない。", "リアクター3台は税抜400万円/台、共同開発3件は税抜150万円/件、着手50％・納品検収50％。売上代金の入金計1,815万円（税込）。価格・受注・支払条件は計画。", "STSは2027年10月交付、補助率2/3、2028年9月まで研究継続。四半期末締め翌月末の実績払いを仮定。採択・対象認定・入金日は未確定。", "補助相当額の支払予定分を四半期初に借り、STS入金と同月に返済。年利2％、手数料0円の融資案。承認済み条件ではない。", "支出は税込の現金予算で、設備・敷金・前払・共同開発追加原価・利息を含む。損益とは一致しないためP/Lを推測して作らない。売上代金は営業C/F、装置・初期費用は投資C/F、借入と返済は独立行へ対応。", "原資料の支出計・売上入金は「元データの内訳」で確認できる。円未満は四捨五入し、月初＋収支＝月末を維持する端数調整のみ記録。", "2028年6月末の現金は1,264.9万円、借入残高475.0万円、補助相当額の未入金171.9万円。研究の期間後前払250万円を含む。", "原資料の期末比較：STSなし・売上入金ありは▲1,470.7万円、STS・売上入金なしは▲3,186.7万円、STSなし＋ブリッジ4,000万円は2,529.3万円、シード1.5億円・主ケースは6,264.9万円。比較を主ケースの入金に混ぜない。", "2028年7月以降の事業・損益・資金計画は今回更新していない。"], "nextRoundYm": "2028-07", "bridgePolicy": [], "monthlyCosts": [], "seedAmountYen": 100000000, "postMoneyCapYen": 500000000, "bridgeEnvelopeYen": 50000000, "nextRoundAmountYen": null, "conversionTriggerYen": 100000000, "improvementTargetYen": 0, "loanFacilityTargetYen": 30000000}}$plan$::jsonb WHERE project_id='p21' AND ym='2027-04';
